import { describe, expect, it } from 'vitest'
import { compareCodePoints, conversations, sortMessages, threadMessages } from './ordering'
import { local, uuid } from './testMessages'

describe('REQ-ORDER-001 message order within a conversation', () => {
  it('REQ-ORDER-001 orders messages with seq ascending, then those without seq by createdAt then id', () => {
    const a = local({ id: uuid(0xa1), seq: 5, status: 'sent', receivedAt: '2026-10-15T10:00:05.000Z' })
    const b = local({ id: uuid(0xa2), seq: 2, status: 'received', from: 'Bob', to: 'Alice' })
    const q1 = local({ id: uuid(0xb2), createdAt: '2026-10-15T09:00:00.000Z' })
    const q2 = local({ id: uuid(0xb1), createdAt: '2026-10-15T09:00:00.000Z', status: 'failed', errorCode: 'x' })
    const q3 = local({ id: uuid(0xb0), createdAt: '2026-10-15T11:00:00.000Z' })
    // Unsent messages come last even if their createdAt is earlier than synced ones.
    expect(sortMessages([q3, a, q1, b, q2]).map((m) => m.id)).toEqual([b.id, a.id, q2.id, q1.id, q3.id])
  })

  it('REQ-ORDER-001 is a pure function of the data (input order does not matter)', () => {
    const ms = [
      local({ seq: 3, status: 'sent' }),
      local({ seq: 1, status: 'sent' }),
      local({ createdAt: '2026-10-15T08:00:00.001Z' }),
      local({ createdAt: '2026-10-15T08:00:00.000Z' }),
    ]
    const expected = sortMessages(ms).map((m) => m.id)
    expect(sortMessages([...ms].reverse()).map((m) => m.id)).toEqual(expected)
  })

  it('REQ-ORDER-001 threadMessages keeps only one peer', () => {
    const toBob = local({ to: 'Bob' })
    const fromBob = local({ from: 'Bob', to: 'Alice', seq: 1, status: 'received' })
    const toCarol = local({ to: 'Carol' })
    expect(threadMessages([toBob, fromBob, toCarol], 'Alice', 'Bob').map((m) => m.id)).toEqual([fromBob.id, toBob.id])
  })
})

describe('REQ-ORDER-002 conversation order', () => {
  it('REQ-ORDER-002 newest activity of the last message first', () => {
    const bob1 = local({ from: 'Bob', to: 'Alice', seq: 1, status: 'received', receivedAt: '2026-10-15T10:00:01.000Z' })
    const carol = local({ from: 'Carol', to: 'Alice', seq: 2, status: 'received', receivedAt: '2026-10-15T10:00:02.000Z' })
    expect(conversations([bob1, carol], 'Alice').map((c) => c.peer)).toEqual(['Carol', 'Bob'])
    const bob2 = local({ from: 'Bob', to: 'Alice', seq: 3, status: 'received', receivedAt: '2026-10-15T10:00:03.000Z' })
    const list = conversations([bob1, carol, bob2], 'Alice')
    expect(list.map((c) => c.peer)).toEqual(['Bob', 'Carol'])
    expect(list[0].last.id).toBe(bob2.id)
  })

  it('REQ-ORDER-002 uses createdAt when receivedAt is null, and the last message in REQ-ORDER-001 order', () => {
    // The queued message is last in REQ-ORDER-001 order, even though a synced one has a later receivedAt.
    const synced = local({ to: 'Bob', seq: 1, status: 'sent', receivedAt: '2026-10-15T12:00:00.000Z' })
    const queued = local({ to: 'Bob', createdAt: '2026-10-15T09:00:00.000Z' })
    const carol = local({ to: 'Carol', seq: 2, status: 'sent', receivedAt: '2026-10-15T10:00:00.000Z' })
    const list = conversations([synced, queued, carol], 'Alice')
    expect(list[0].peer).toBe('Carol')
    expect(list[1]).toEqual({ peer: 'Bob', last: queued })
  })

  it('REQ-ORDER-002 ties are broken by peer name ascending in code-point order', () => {
    const t = '2026-10-15T10:00:00.000Z'
    const ms = [
      local({ to: 'bob', receivedAt: t, seq: 1, status: 'sent' }),
      local({ to: 'Bob', receivedAt: t, seq: 2, status: 'sent' }),
      local({ to: '_x', receivedAt: t, seq: 3, status: 'sent' }),
    ]
    expect(conversations(ms, 'Alice').map((c) => c.peer)).toEqual(['Bob', '_x', 'bob'])
  })

  it('REQ-ORDER-002 compareCodePoints is code-point order, not UTF-16 order', () => {
    expect(compareCodePoints('￿', '😀')).toBe(-1)
    expect(compareCodePoints('a', 'ab')).toBe(-1)
    expect(compareCodePoints('b', 'a')).toBe(1)
    expect(compareCodePoints('x', 'x')).toBe(0)
  })

  it('REQ-ORDER-002 has no conversation without messages', () => {
    expect(conversations([], 'Alice')).toEqual([])
  })
})
